record.field:
model = env['quo.call'].sudo()
calls = model.search([('transcript_id', '=', False)], limit=25)
for c in calls:
    try:
        payload = model._quo_get(f"call-transcripts/{c.quo_call_id}")
        transcript_obj = payload.get("data") if isinstance(payload, dict) and "data" in payload else payload
        env['quo.call.transcript'].sudo().upsert_from_transcript_payload(c.quo_call_id, transcript_obj if isinstance(transcript_obj, dict) else {})
    except Exception:
        # swallow; will retry later
        pass
